    }
  ],
  "constraints": [
    "Defining google_search does not execute its body.",
    "module.is_main is module.name == '__main__'.",
    "The function definition establishes the default num_results value 5."
  ],
  "metadata": {
    "source_span": {
      "file": "skill/scripts/search.py",
      "start_line": 6,
      "end_line": 18
    },
    "script_content": "def google_search(query, api_key, cse_id, num_results=5):\n    url = \"https://www.googleapis.com/customsearch/v1\"\n    params = {\n        'q': query,\n        'key': api_key,\n        'cx': cse_id,\n        'num': num_results\n    }\n    response = requests.get(url, params=params)\n    response.raise_for_status()\n    return response.json()\n\nif __name__ == \"__main__\":\n",
    "source_actions": [
      {
        "ref": "define_google_search",
        "kind": "value",
        "source": {
          "file": "skill/scripts/search.py",
          "start_line": 6,
          "end_line": 16
        }
      },
      {
        "ref": "compare_module_name",
        "kind": "value",
        "source": {
          "file": "skill/scripts/search.py",
          "start_line": 18,
