{
  "id": "ir_013",
  "opcode": "return",
  "inputs": [],
  "outputs": [],
  "constraints": [],
  "metadata": {
    "target": "Python module evaluator",
    "completion": "normal module completion",
    "source_span": {
      "file": "skill/scripts/search.py",
      "start_line": 18,
      "end_line": 39
    },
    "script_content": "if __name__ == \"__main__\":\n    if len(sys.argv) < 2:\n        print(\"Usage: python google_search.py <query> [num_results]\")\n        sys.exit(1)\n\n    query = sys.argv[1]\n    num_results = int(sys.argv[2]) if len(sys.argv) > 2 else 5\n    \n    # We will pass these via env vars for security\n    api_key = os.getenv(\"GOOGLE_API_KEY\")\n    cse_id = os.getenv(\"GOOGLE_CSE_ID\")\n\n    if not api_key or not cse_id:\n        print(\"Error: GOOGLE_API_KEY and GOOGLE_CSE_ID must be set in environment.\")\n        sys.exit(1)\n\n    try:\n        results = google_search(query, api_key, cse_id, num_results)\n        print(json.dumps(results, indent=2))\n    except Exception as e:\n        print(f\"Error: {str(e)}\")\n        sys.exit(1)\n",
    "source_actions": [
      {
        "ref": "exit",
        "kind": "return",
        "source": {
          "file": "skill/scripts/search.py",
          "start_line": 18,
          "end_line": 39
        },
        "role": "other"
      }
    ]
  },
  "draft_instruction_id": "/blocks/module.done/exit"
}

